"""Westside Watch 8:5 motion stream using the verified local Codrops interaction."""
PAGE_ID='motion-codrops-site-8x5'

def _page():
    return {'id':PAGE_ID,'name':'Motion · Westside Watch 8:5','canvas':{'w':1440,'h':960},'nodes':[],'design_experiment':{'schema':'dore.design-experiment.v1','track':'motion-language','prototype':'westside-watch-8x5','status':'design-candidate','source':'local verified Codrops-motion reproduction','principles':['freeze-motion-engine','brand-content-only','eight-by-five','weighted-reading-stream','westside-watch','one-live-source-first-card','one-live-content-preview']}}

def install_workspace(base):
    original=base.workspace
    def workspace():
        w=original()
        for p in w.get('pages',[]):
            if p.get('id')==PAGE_ID:p.update(_page());return base.save(w)
        w['pages'].append(_page());return base.save(w)
    base.workspace=workspace

def install_editor(html):return html

def render(edit=False):
    badge='<div class="dore-badge">DORÉ DESIGN · WESTSIDE WATCH · 8:5 MOTION</div>' if edit else ''
    base='https://tympanus.net/Tutorials/GridToFullPreview/assets/products/'
    items=[
      ('ONE','馬太福音第七章','讀取 ONE…','/one/?book=40&chapter=7'),
      ('JOURNAL','米斯巴','守望 · Journal','/journal/'),
      ('DAWN LIBRARY','黎明書局','Dawn Library','/website/dawn-library/'),
      ('FEATURE','看見','Feature · Journal','/journal/'),
      ('PRAYER','瑪拉拿','Prayer · Journal','/journal/'),
      ('WITNESS','見證人','Witness · Journal','/journal/'),
      ('DIALOGUE','守望者 · 對話','Dialogue · Journal','/journal/'),
      ('LIVING WATER','活水堂西區','Living Water Assembly West','/church/'),
    ]
    products=[];previews=[]
    for i,(kind,title,sub,href) in enumerate(items,1):
        idx=i-1
        one_attrs=' data-source="ONE" data-book="40" data-chapter="7"' if idx==0 else ''
        products.append(f'''<li class="product" data-name="{title}" data-kind="{kind}" data-sub="{sub}" data-href="{href}" data-index="{idx}"{one_attrs}><img src="{base}product-{i}.webp" alt=""><div class="brand-shade"></div><div class="brand-copy"><small>{kind}</small><strong>{title}</strong><span>{sub}</span></div></li>''')
        previews.append(''.join([f'<img data-id="{idx}" src="{base}product-{i}.webp" alt="">',f'<img data-id="{idx}" src="{base}product-{i}-detail-1.webp" alt="">',f'<img data-id="{idx}" src="{base}product-{i}-detail-2.webp" alt="">']))
    products=''.join(products);previews=''.join(previews)
    one_preview='''<article class="one-live-preview" hidden><div class="one-live-copy"><small>ONE · CHAPTER PREVIEW</small><h2 class="one-live-title"></h2><p class="one-live-passage"></p><p class="one-live-story"></p><ol class="one-live-route"></ol><span class="one-live-cta">進入 ONE 閱讀完整章節 →</span></div><div class="one-live-media"><figure><img class="one-live-art" alt=""><figcaption class="one-live-art-caption"></figcaption></figure><figure><img class="one-live-map" alt=""><figcaption class="one-live-map-caption"></figcaption></figure></div></article>'''
    return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Westside Watch · 8:5</title><style>
*{{box-sizing:border-box}}html,body{{margin:0;min-height:100%;background:#eee8da;color:#252525;font-family:"Noto Serif TC",Georgia,serif}}body{{overflow-x:hidden}}.dore-badge{{position:fixed;z-index:99;top:8px;left:8px;background:#252525;color:#cebd74;padding:7px 9px;font:9px ui-monospace,monospace;letter-spacing:.12em}}.frame{{height:92px;display:grid;grid-template-columns:1fr auto auto;gap:30px;align-items:center;padding:0 4vw;border-bottom:1px solid rgba(37,37,37,.12)}}.frame h1{{font:26px "Cormorant Garamond",Georgia,serif;font-weight:400;margin:0;letter-spacing:.02em}}.frame span{{font:10px ui-monospace,monospace;letter-spacing:.13em;text-transform:uppercase}}.frame em{{font-style:normal;color:#8b8066}}.cats{{display:flex;justify-content:center;gap:25px;padding:14px 0 2px;font-size:13px}}.cats span:first-child{{color:#9b884c}}.products{{position:relative;min-height:calc(100vh - 108px);padding:48px}}.products__grid,.products__preview{{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-template-rows:repeat(2,auto);gap:5vw;align-content:center}}.products__grid{{list-style:none;margin:0;padding:0;min-height:calc(100vh - 204px)}}.product{{position:relative;aspect-ratio:8/5;overflow:hidden;background:#d7cfbd;transform:translate3d(0,0,0);will-change:transform,opacity;cursor:pointer}}.product>img{{width:100%;height:100%;display:block;object-fit:cover;filter:saturate(.58) contrast(.92)}}.brand-shade{{position:absolute;inset:0;background:linear-gradient(0deg,rgba(18,17,13,.78),rgba(18,17,13,.04) 70%)}}.brand-copy{{position:absolute;inset:0;padding:15px;display:flex;flex-direction:column;justify-content:flex-end;color:#f5f0e4;pointer-events:none}}.brand-copy small{{font:9px ui-monospace,monospace;letter-spacing:.16em;color:#cebd74}}.brand-copy strong{{font:400 clamp(17px,1.55vw,27px) "Noto Serif TC",Georgia,serif;margin-top:4px}}.brand-copy span{{font:10px ui-monospace,monospace;opacity:.72;margin-top:5px}}.products__preview{{position:absolute;inset:48px;pointer-events:none;min-height:calc(100vh - 204px)}}.product-preview{{position:absolute;top:50%;width:calc(50% - 2.5vw);height:100%;transform:translateY(-50%);opacity:0;overflow:hidden;background:#171713;will-change:opacity,transform}}.product-preview.--left{{left:0}}.product-preview.--right{{right:0}}.product-preview__images{{position:absolute;inset:0}}.product-preview__images img{{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;filter:saturate(.62)}}.product-preview__details{{position:absolute;z-index:4;left:22px;bottom:20px;color:#f4efe3;text-shadow:0 1px 8px #000}}.product-preview__details small{{font:9px ui-monospace,monospace;letter-spacing:.15em;color:#cebd74}}.product-preview__details p{{font-size:24px;margin:4px 0}}.product-preview__details span{{font:10px ui-monospace,monospace;opacity:.75}}.masked-preview{{position:absolute;inset:0;background:#eee8da;clip-path:polygon(45% 0,55% 0,55% 45%,100% 45%,100% 55%,55% 55%,55% 100%,45% 100%,45% 55%,0 55%,0 45%,45% 45%);will-change:clip-path;z-index:8}}
.one-live-preview{{position:absolute;inset:0;z-index:3;display:grid;grid-template-columns:minmax(0,1.2fr) minmax(150px,.8fr);gap:24px;padding:clamp(24px,3vw,48px);background:linear-gradient(125deg,#f0eadb 0%,#e7dfcf 58%,#d8cfbd 100%);color:#252525;overflow:hidden}}.one-live-preview[hidden]{{display:none}}.one-live-copy{{min-width:0;display:flex;flex-direction:column;justify-content:center}}.one-live-copy small{{font:9px ui-monospace,monospace;letter-spacing:.16em;color:#8d793f}}.one-live-copy h2{{font:400 clamp(29px,3.4vw,58px)/.98 "Noto Serif TC",Georgia,serif;margin:12px 0 7px;max-width:10em}}.one-live-passage{{font:11px ui-monospace,monospace;letter-spacing:.08em;margin:0 0 22px;color:#6f654f}}.one-live-story{{font-size:clamp(13px,1.15vw,17px);line-height:1.8;max-width:44em;margin:0 0 18px}}.one-live-route{{list-style:none;margin:0;padding:0;border-top:1px solid rgba(37,37,37,.16)}}.one-live-route li{{display:grid;grid-template-columns:64px 1fr;gap:12px;padding:7px 0;border-bottom:1px solid rgba(37,37,37,.12);font-size:11px;line-height:1.45}}.one-live-route b{{font:9px ui-monospace,monospace;color:#8d793f}}.one-live-cta{{margin-top:18px;font:10px ui-monospace,monospace;letter-spacing:.08em;color:#5f543c}}.one-live-media{{display:grid;grid-template-rows:1.15fr .85fr;gap:12px;min-width:0}}.one-live-media figure{{position:relative;margin:0;overflow:hidden;background:#c8bfac;border:1px solid rgba(37,37,37,.13)}}.one-live-media img{{width:100%;height:100%;object-fit:cover;display:block;filter:saturate(.45) contrast(.93)}}.one-live-media figcaption{{position:absolute;left:9px;right:9px;bottom:7px;font:8px/1.35 ui-monospace,monospace;letter-spacing:.04em;color:#f7f0e3;text-shadow:0 1px 5px rgba(0,0,0,.9)}}.product-preview.is-one-live .product-preview__details{{display:none}}
@media(max-width:1100px){{.one-live-preview{{grid-template-columns:1fr;padding:26px}}.one-live-media{{display:none}}.one-live-copy h2{{font-size:35px}}.one-live-story{{font-size:13px}}}}@media(max-width:900px){{.products__grid{{grid-template-columns:repeat(2,1fr)}}.products__preview{{display:none}}.frame{{grid-template-columns:1fr}}.frame span,.frame em{{display:none}}}}
</style></head><body>{badge}<header class="frame"><h1>Westside Watch</h1><span>Watch for the Dawn</span><em>ONE · JOURNAL · DAWN LIBRARY · LIVING WATER</em></header><nav class="cats"><span>守望</span><span>查經</span><span>閱讀</span><span>見證</span><span>禱告</span><span>對話</span></nav><main class="products"><ul class="products__grid">{products}</ul><div class="products__preview"><div class="product-preview --left"><div class="product-preview__images">{previews}</div>{one_preview}<div class="product-preview__details"><small class="preview-kind"></small><p class="product-title"></p><span class="preview-sub"></span></div><div class="masked-preview"></div></div><div class="product-preview --right"><div class="product-preview__images">{previews}</div>{one_preview}<div class="product-preview__details"><small class="preview-kind"></small><p class="product-title"></p><span class="preview-sub"></span></div><div class="masked-preview"></div></div></div></main>
<script src="/one/one-data.js"></script><script src="/one/matthew-complete.js"></script>
<script>(()=>{{
 const card=document.querySelector('.product[data-source="ONE"][data-book="40"][data-chapter="7"]');
 const study=window.ONE_DATA?.matthew?.chapterStudies?.['7'];
 if(card&&study){{
   const title=study.title||window.ONE_DATA.matthew.chapters?.[6]||'馬太福音第七章';
   const passage=study.passage||'馬太福音 7';
   const sub=`${{passage}} · ${{study.movement||''}}`.replace(/ · $/,'');
   const href='/one/?book=40&chapter=7';
   const image=study.illustration?.src;
   card.dataset.name=title;card.dataset.kind='ONE · 馬太福音';card.dataset.sub=sub;card.dataset.href=href;
   card.querySelector('.brand-copy small').textContent='ONE · 馬太福音';card.querySelector('.brand-copy strong').textContent=title;card.querySelector('.brand-copy span').textContent=sub;
   if(image){{card.querySelector(':scope > img').src=image;card.querySelector(':scope > img').alt=study.illustration?.alt||title}}
   document.querySelectorAll('.one-live-preview').forEach(panel=>{{
     panel.querySelector('.one-live-title').textContent=title;
     panel.querySelector('.one-live-passage').textContent=sub;
     panel.querySelector('.one-live-story').textContent=study.story||study.position||'';
     panel.querySelector('.one-live-route').innerHTML=(study.route||[]).slice(0,4).map(row=>`<li><b>${{row[0]||''}}</b><span>${{row[1]||''}}</span></li>`).join('');
     const art=panel.querySelector('.one-live-art'),map=panel.querySelector('.one-live-map');
     if(study.illustration?.src){{art.src=study.illustration.src;art.alt=study.illustration.alt||title;panel.querySelector('.one-live-art-caption').textContent=study.illustration.title||'古斯塔夫・多雷'}} else art.closest('figure').hidden=true;
     if(study.map?.image){{map.src=study.map.image;map.alt=study.map.imageTitle||study.map.title||title;panel.querySelector('.one-live-map-caption').textContent=study.map.title||study.map.imageTitle||'本章地圖'}} else map.closest('figure').hidden=true;
   }});
   card.dataset.oneBound='true';document.documentElement.dataset.oneCard='matthew-7-live';
 }} else {{document.documentElement.dataset.oneCard='missing'}}
}})();</script>
<script>(()=>{{const products=[...document.querySelectorAll('.product')],left=document.querySelector('.product-preview.--left'),right=document.querySelector('.product-preview.--right');let timer=null,active=null,gallery=null,animations=[];const thick='polygon(45% 0,55% 0,55% 45%,100% 45%,100% 55%,55% 55%,55% 100%,45% 100%,45% 55%,0 55%,0 45%,45% 45%)',thin='polygon(50% 0,50% 0,50% 50%,100% 50%,100% 50%,50% 50%,50% 100%,50% 100%,50% 50%,0 50%,0 50%,50% 50%)';function stop(){{animations.forEach(a=>{{try{{a.cancel()}}catch(e){{}}}});animations=[]}}function pv(p){{let i=+p.dataset.index;return(i%4===0||i%4===1)?right:left}}function side(p){{let i=+p.dataset.index,l=i%4<2;return products.filter(x=>l?(+x.dataset.index)%4<2:(+x.dataset.index)%4>=2)}}function setMode(preview,p){{const live=p.dataset.source==='ONE'&&p.dataset.oneBound==='true',panel=preview.querySelector('.one-live-preview'),images=preview.querySelector('.product-preview__images');preview.classList.toggle('is-one-live',live);panel.hidden=!live;images.hidden=live;return live}}function imgs(preview,id){{let all=[...preview.querySelectorAll('.product-preview__images img')];all.forEach(x=>x.style.opacity=0);let a=all.filter(x=>x.dataset.id==id),k=0;if(a.length)a[0].style.opacity=1;clearInterval(gallery);gallery=setInterval(()=>{{a.forEach(x=>x.style.opacity=0);if(a.length){{k=(k+1)%a.length;a[k].style.opacity=1}}}},500)}}function enter(p){{active=p;stop();clearInterval(gallery);let preview=pv(p),s=side(p),id=+p.dataset.index,live=setMode(preview,p);preview.querySelector('.preview-kind').textContent=p.dataset.kind;preview.querySelector('.product-title').textContent=p.dataset.name;preview.querySelector('.preview-sub').textContent=p.dataset.sub;if(!live)imgs(preview,id);animations.push(preview.animate([{{opacity:0,transform:'translateY(-50%) scale(.94)'}},{{opacity:1,transform:'translateY(-50%) scale(1)'}}],{{duration:650,easing:'cubic-bezier(.65,0,.2,1)',fill:'forwards'}}));let mask=preview.querySelector('.masked-preview');animations.push(mask.animate([{{clipPath:thick}},{{clipPath:thin}}],{{duration:650,easing:'cubic-bezier(.65,0,.2,1)',fill:'forwards'}}));s.forEach(x=>{{let j=+x.dataset.index,col=j%4,row=j<4?0:1,dx=(col%2===0?1:-1)*2.5,dy=(row===0?1:-1)*2.5;animations.push(x.animate([{{opacity:1,transform:'translate(0,0)'}},{{opacity:0,transform:`translate(${{dx}}vw,${{dy}}vw)`}}],{{duration:650,easing:'cubic-bezier(.65,0,.2,1)',fill:'forwards'}}))}})}}function leave(){{if(timer){{clearTimeout(timer);timer=null}}if(!active)return;stop();clearInterval(gallery);let p=active,preview=pv(p),s=side(p),mask=preview.querySelector('.masked-preview');animations.push(preview.animate([{{opacity:1,transform:'translateY(-50%) scale(1)'}},{{opacity:0,transform:'translateY(-50%) scale(.94)'}}],{{duration:520,easing:'cubic-bezier(.65,0,.2,1)',fill:'forwards'}}));animations.push(mask.animate([{{clipPath:thin}},{{clipPath:thick}}],{{duration:520,easing:'cubic-bezier(.65,0,.2,1)',fill:'forwards'}}));s.forEach(x=>{{let cs=getComputedStyle(x);animations.push(x.animate([{{opacity:cs.opacity,transform:cs.transform==='none'?'translate(0,0)':cs.transform}},{{opacity:1,transform:'translate(0,0)'}}],{{duration:520,easing:'cubic-bezier(.65,0,.2,1)',fill:'forwards'}}))}});active=null}}products.forEach(p=>{{p.addEventListener('mouseenter',()=>{{clearTimeout(timer);timer=setTimeout(()=>{{enter(p);timer=null}},100)}});p.addEventListener('mouseleave',leave);p.addEventListener('click',()=>{{location.href=p.dataset.href}})}});document.documentElement.dataset.motion='ready'}})();</script></body></html>'''
